// A quiet original instrumental: plucked strings, open fifths and a soft drone.
export class Atmosphere {
 constructor(){this.context=null;this.playing=false;this.step=0;this.timer=null}
 async toggle(){if(!this.context){const C=window.AudioContext||window.webkitAudioContext;if(!C)throw new Error('Audio is unavailable in this browser.');this.context=new C();this.master=this.context.createGain();this.master.gain.value=0;this.master.connect(this.context.destination);const delay=this.context.createDelay(1.5),feedback=this.context.createGain();delay.delayTime.value=.43;feedback.gain.value=.21;delay.connect(feedback);feedback.connect(delay);delay.connect(this.master);this.echo=delay}
 await this.context.resume();this.playing=!this.playing;this.master.gain.setTargetAtTime(this.playing?.035:0,this.context.currentTime,.45);if(this.playing){this.note();this.timer=setInterval(()=>this.note(),1350)}else{clearInterval(this.timer);this.timer=null}return this.playing}
 note(){if(!this.playing)return;const ac=this.context,t=ac.currentTime;const melody=[146.83,220,293.66,329.63,293.66,220,196,164.81,146.83,220,261.63,293.66,261.63,220,196,146.83];const base=melody[this.step%melody.length];for(let i=0;i<3;i++){const osc=ac.createOscillator(),gain=ac.createGain(),filter=ac.createBiquadFilter();osc.type=i?'sine':'triangle';osc.frequency.value=base*(i===2?.5:i===1?2:1);filter.type='lowpass';filter.frequency.value=900;gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(i?.1:.36,t+.018);gain.gain.exponentialRampToValueAtTime(.001,t+3.8);osc.connect(filter);filter.connect(gain);gain.connect(this.master);gain.connect(this.echo);osc.start(t);osc.stop(t+4)}this.step++}
 fade(progress){if(this.playing&&this.context)this.master.gain.setTargetAtTime(.035*(1-Math.max(0,(progress-.98)/.02)*.8),this.context.currentTime,.5)}
}
